// Dev-only helper: collects translation keys that fell back to their default and,
// after a debounce, logs them as a ready-to-send curl for the translations API.
// Behind a localStorage flag — a no-op in production unless explicitly enabled.
// Shared so each widget configures just its key/namespace/log prefix.

export interface MissingKeysHelperConfig {
  /** localStorage flag that enables the helper (set to 'true'). */
  lsKey: string;
  /** i18n namespace defaulted when a caller omits one. */
  namespace: string;
  /** Wordplex grid uuid for the request-translations payload. */
  gridUuid: string;
  /** Base URL of the translations API. */
  prodUrl: string;
  /** Console label, e.g. "[uploader]". */
  logPrefix: string;
}

export interface MissingKeysHelper {
  handleMissingKey(key: string, value?: string, ns?: string): void;
}

export function createMissingKeysHelper(config: MissingKeysHelperConfig): MissingKeysHelper {
  const { lsKey, namespace, gridUuid, prodUrl, logPrefix } = config;
  const enabled = typeof localStorage !== 'undefined' && localStorage.getItem(lsKey) === 'true';
  const missingKeys: Record<string, { value: string; ns: string }> = {};
  let timer: ReturnType<typeof setTimeout> | null = null;
  const debounceDelay = 2000;

  if (enabled) {
    console.log(`%c${logPrefix} TranslationMissingKeysHelper enabled`, 'font-weight:600;');
  }

  const renderCurl = () => {
    console.group(`${logPrefix} Missing translation keys`);
    console.log('%cMissing keys:', 'font-weight:600;font-size:200%;');
    console.table({ ...missingKeys });
    console.log('%ccURL (check carefully data before send):', 'font-weight:600;font-size:150%;');
    console.log(`
curl '${prodUrl}/api/import/request-translations' \\
  --data-raw '{"grid_uuid":"${gridUuid}","translations_requests":${JSON.stringify(
    Object.entries(missingKeys).map(([mapKey, { value, ns }]) => ({
      key: ns && mapKey.startsWith(`${ns}:`) ? mapKey.slice(ns.length + 1) : mapKey,
      lang: 'en',
      default: value,
    })),
  ).replaceAll("'", "'\\''")}}'
    `);
    console.groupEnd();
  };

  return {
    handleMissingKey(key: string, value = '', ns = namespace) {
      if (!enabled) return;
      missingKeys[`${ns}:${key}`] = { value, ns };
      if (timer) clearTimeout(timer);
      timer = setTimeout(renderCurl, debounceDelay);
    },
  };
}
