import { LitElement, html, css, nothing, type PropertyValues } from 'lit';
import { property, state } from 'lit/decorators.js';
import { resetStyles } from '../styles/reset';
import { touchInputStyles } from '../styles/forms';
import { cspStyle } from '../utils/csp-style';
import { customElement } from '../utils/define-element';
import './sfx-calendar';
import './sfx-icon';

function parseIsoDate(value: string): Date | null {
  if (!value) return null;
  const [y, m, d] = value.split('-').map(Number);
  if (!y || !m || !d) return null;
  return new Date(y, m - 1, d);
}

function toIsoDate(date: Date): string {
  const y = date.getFullYear();
  const m = String(date.getMonth() + 1).padStart(2, '0');
  const d = String(date.getDate()).padStart(2, '0');
  return `${y}-${m}-${d}`;
}

/** month/day/year order for the locale, e.g. `['month','day','year']` for en-US. */
function dateFieldOrder(locale: string): Array<'month' | 'day' | 'year'> {
  return new Intl.DateTimeFormat(locale, { year: 'numeric', month: '2-digit', day: '2-digit' })
    .formatToParts(new Date(2000, 0, 1))
    .map((part) => part.type)
    .filter(
      (type): type is 'month' | 'day' | 'year' =>
        type === 'month' || type === 'day' || type === 'year',
    );
}

/** Builds a locale-aware format hint (e.g. `MM/DD/YYYY`, `DD/MM/YYYY`) from Intl's part order. */
function formatHint(locale: string): string {
  return new Intl.DateTimeFormat(locale, { year: 'numeric', month: '2-digit', day: '2-digit' })
    .formatToParts(new Date(2000, 0, 1))
    .map((part) => {
      switch (part.type) {
        case 'month':
          return 'MM';
        case 'day':
          return 'DD';
        case 'year':
          return 'YYYY';
        default:
          return part.value;
      }
    })
    .join('');
}

/** Parses free-typed text (e.g. `07/31/2026`) using the locale's field order. Rejects incomplete/invalid input. */
function parseTypedDate(text: string, locale: string): Date | null {
  const segments = text.split(/[^0-9]+/).filter(Boolean);
  if (segments.length !== 3) return null;
  const order = dateFieldOrder(locale);
  const parts: Partial<Record<'month' | 'day' | 'year', number>> = {};
  for (const [i, type] of order.entries()) {
    const segment = segments[i];
    // Require a full 4-digit year and at-most-2-digit month/day — otherwise a
    // partial year like "202" can round-trip through `new Date()` as "valid".
    if (type === 'year' ? segment.length !== 4 : segment.length > 2) return null;
    parts[type] = Number(segment);
  }
  const { month, day, year } = parts;
  if (!month || !day || !year || month < 1 || month > 12 || day < 1 || day > 31) return null;
  const date = new Date(year, month - 1, day);
  if (date.getFullYear() !== year || date.getMonth() !== month - 1 || date.getDate() !== day) {
    return null;
  }
  return date;
}

/**
 * Drop-in replacement for `<input type="date">`: same `value`/`min`/`max` (ISO
 * `YYYY-MM-DD` strings) contract and fires a `change` event whose `target.value`
 * reflects the new value — existing `(e.target as HTMLInputElement).value` handlers
 * keep working unchanged. The field is a real, editable text input — users can type
 * a date directly (validated live, locale-aware format) — and only the calendar
 * icon opens the `sfx-calendar` popover, matching the hub's `@scaleflex/ui-tw`
 * DatePicker.
 */
@customElement('sfx-date-input')
export class SfxDateInput extends LitElement {
  static styles = [
    resetStyles,
    touchInputStyles,
    css`
      :host {
        position: relative;
        display: inline-block;
        width: 100%;
        min-width: 0;
      }
      .field {
        display: flex;
        align-items: center;
        width: 100%;
        height: 36px;
        padding: 0 10px;
        box-sizing: border-box;
        border: 1px solid var(--sfx-input, oklch(0.871 0.016 241.798));
        border-radius: var(--sfx-radius-sm, 6px);
        background: var(--sfx-background, oklch(1 0 0));
      }
      .field:hover:not(.disabled) {
        border-color: var(--sfx-muted-foreground, oklch(0.685 0.033 249.82));
      }
      .field.disabled {
        opacity: 0.5;
      }
      .field.open,
      .field:focus-within {
        border-color: var(--sfx-primary, oklch(0.578 0.198 268.129));
      }
      .field.error {
        border-color: var(--sfx-destructive, oklch(0.577 0.215 27.325));
      }
      input {
        flex: 1;
        min-width: 0;
        border: none;
        outline: none;
        background: none;
        padding: 0;
        margin: 0;
        color: var(--sfx-foreground, oklch(0.37 0.022 248.413));
        font-family: inherit;
        font-size: var(--sfx-font-size-sm, 0.875rem);
      }
      input:disabled {
        cursor: default;
      }
      input::placeholder {
        color: var(--sfx-muted-foreground, oklch(0.685 0.033 249.82));
      }
      .icon-btn {
        display: flex;
        align-items: center;
        justify-content: center;
        flex-shrink: 0;
        margin-left: 8px;
        padding: 0;
        border: none;
        background: none;
        color: var(--sfx-muted-foreground, oklch(0.685 0.033 249.82));
        cursor: pointer;
      }
      .icon-btn:disabled {
        cursor: default;
      }
      .error-text {
        font-size: 0.8125rem;
        color: var(--sfx-destructive, oklch(0.577 0.215 27.325));
        margin-top: 4px;
      }
      .popover {
        position: fixed;
        z-index: 50;
        background: var(--sfx-card, oklch(1 0 0));
        border: 1px solid var(--sfx-border, oklch(92.86% 0.009 247.92));
        border-radius: var(--sfx-radius, 8px);
        box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1);
        padding: 10px;
      }
    `,
  ];

  @property() value = '';
  @property() min = '';
  @property() max = '';
  @property() placeholder = '';
  @property({ type: Boolean }) disabled = false;
  @property() locale = '';

  @state() private _draft = '';
  @state() private _error = '';
  @state() private _open = false;
  @state() private _popoverTop = 0;
  @state() private _popoverBottom = 0;
  @state() private _popoverLeft = 0;
  @state() private _popoverPosition: 'below' | 'above' = 'below';

  private get _effectiveLocale(): string {
    return this.locale || document.documentElement.lang || 'en';
  }

  private get _selectedDate(): Date | null {
    return parseIsoDate(this.value);
  }

  private get _displayText(): string {
    const date = this._selectedDate;
    if (!date) return '';
    return new Intl.DateTimeFormat(this._effectiveLocale).format(date);
  }

  protected willUpdate(changed: PropertyValues<this>) {
    if (changed.has('value') && this.shadowRoot?.activeElement?.tagName !== 'INPUT') {
      this._draft = this._displayText;
      this._error = '';
    }
  }

  render() {
    const date = this._selectedDate;
    return html`
      <div
        class="field ${this._open ? 'open' : ''} ${this.disabled ? 'disabled' : ''} ${this._error
          ? 'error'
          : ''}"
      >
        <input
          type="text"
          .value=${this._draft}
          placeholder=${this.placeholder || formatHint(this._effectiveLocale)}
          ?disabled=${this.disabled}
          @input=${this._handleInput}
        />
        <button
          class="icon-btn"
          type="button"
          aria-label="Open calendar"
          ?disabled=${this.disabled}
          @click=${this._toggleCalendar}
        >
          <sfx-icon name="calendar" .size=${16}></sfx-icon>
        </button>
      </div>
      ${this._error ? html`<div class="error-text">${this._error}</div>` : nothing}
      ${this._open
        ? html`
            <div
              class="popover"
              ${cspStyle({
                [this._popoverPosition === 'below' ? 'top' : 'bottom']:
                  `${this._popoverPosition === 'below' ? this._popoverTop : this._popoverBottom}px`,
                left: `${this._popoverLeft}px`,
              })}
            >
              <sfx-calendar
                .value=${date}
                .minDate=${parseIsoDate(this.min)}
                .maxDate=${parseIsoDate(this.max)}
                .locale=${this.locale}
                @sfx-select=${this._handleSelect}
              ></sfx-calendar>
            </div>
          `
        : nothing}
    `;
  }

  private _handleInput(e: Event) {
    this._draft = (e.target as HTMLInputElement).value;
    this._validateAndCommit(this._draft);
  }

  private _validateAndCommit(text: string) {
    if (!text) {
      this._error = '';
      this._commit('');
      return;
    }
    const parsed = parseTypedDate(text, this._effectiveLocale);
    const minDate = parseIsoDate(this.min);
    const maxDate = parseIsoDate(this.max);
    const outOfRange =
      !!parsed && ((!!minDate && parsed < minDate) || (!!maxDate && parsed > maxDate));
    if (!parsed || outOfRange) {
      this._error = `Invalid date. Use ${formatHint(this._effectiveLocale)}`;
      return;
    }
    this._error = '';
    this._commit(toIsoDate(parsed));
  }

  private _commit(isoValue: string) {
    if (isoValue === this.value) return;
    this.value = isoValue;
    this.dispatchEvent(new Event('change', { bubbles: true, composed: true }));
  }

  private _openCalendar = () => {
    if (this.disabled || this._open) return;
    this._open = true;
    this._updatePopoverPosition();
    document.addEventListener('click', this._handleOutsideClick);
    document.addEventListener('keydown', this._handleKeyDown);
  };

  private _toggleCalendar = () => {
    if (this.disabled) return;
    if (this._open) {
      this._open = false;
      this._cleanupListeners();
    } else {
      this._openCalendar();
    }
  };

  private _handleSelect(e: CustomEvent<{ date: Date }>) {
    this._open = false;
    this._cleanupListeners();
    this._error = '';
    this._commit(toIsoDate(e.detail.date));
  }

  private _updatePopoverPosition() {
    const rect = this.getBoundingClientRect();
    const popoverHeight = 340;
    const spaceBelow = window.innerHeight - rect.bottom;
    const spaceAbove = rect.top;
    this._popoverPosition =
      spaceBelow < popoverHeight && spaceAbove > spaceBelow ? 'above' : 'below';
    if (this._popoverPosition === 'below') {
      this._popoverTop = rect.bottom + 4;
    } else {
      this._popoverBottom = window.innerHeight - rect.top + 4;
    }
    this._popoverLeft = Math.min(rect.left, window.innerWidth - 284);
  }

  private _cleanupListeners() {
    document.removeEventListener('click', this._handleOutsideClick);
    document.removeEventListener('keydown', this._handleKeyDown);
  }

  private _handleOutsideClick = (e: Event) => {
    if (this._open && !e.composedPath().includes(this)) {
      this._open = false;
      this._cleanupListeners();
    }
  };

  private _handleKeyDown = (e: KeyboardEvent) => {
    if (e.key === 'Escape' && this._open) {
      e.preventDefault();
      e.stopPropagation();
      this._open = false;
      this._cleanupListeners();
    }
  };

  disconnectedCallback() {
    super.disconnectedCallback();
    this._cleanupListeners();
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'sfx-date-input': SfxDateInput;
  }
}
