// FUTURE @scaleflex/dam-core — REST client. See ../README.md.
//
// Unifies @scaleflex/asset-picker's `ApiClient` (request/post) with the PUT/DELETE
// verbs light-dam needs for asset/folder mutations. Built on a resolved auth
// (base URL + headers) so it stays decoupled from how auth was obtained.
import { resolveAuth } from '../auth';
import type { AuthConfig, AuthHeaders, ResolvedAuth } from '../auth';

const TIMEOUT_MS = 30_000;

type Params = Record<string, unknown>;

export class DamClient {
  /** REST base, e.g. "https://api.filerobot.com/akli/v5". */
  private readonly baseUrl: string;
  private headers: AuthHeaders;
  // Kept so a short-lived security-template key can be re-exchanged on 401.
  private readonly auth?: AuthConfig;
  private readonly apiDomain?: string;

  constructor(resolved: ResolvedAuth, auth?: AuthConfig, apiDomain?: string) {
    this.baseUrl = `${resolved.apiBase}/v5`;
    this.headers = resolved.headers;
    this.auth = auth;
    this.apiDomain = apiDomain;
  }

  /** Resolve an AuthConfig (performing key exchange if needed) and build a client. */
  static async create(auth: AuthConfig, apiDomain?: string): Promise<DamClient> {
    const resolved = await resolveAuth(auth, apiDomain);
    return new DamClient(resolved, auth, apiDomain);
  }

  get<T>(path: string, params?: Params): Promise<T> {
    const url = new URL(`${this.baseUrl}${path}`);
    if (params) {
      for (const [key, value] of Object.entries(params)) {
        if (value === undefined || value === null) continue;
        url.searchParams.set(key, Array.isArray(value) ? value.join(',') : String(value));
      }
    }
    return this.send<T>(url, { method: 'GET' });
  }

  post<T>(path: string, body: unknown): Promise<T> {
    return this.sendJson<T>('POST', path, body);
  }

  put<T>(path: string, body: unknown): Promise<T> {
    return this.sendJson<T>('PUT', path, body);
  }

  delete<T>(path: string, body?: unknown): Promise<T> {
    return this.sendJson<T>('DELETE', path, body);
  }

  /**
   * Absolute REST URL (incl. the `/v5` base) for a path — for building direct
   * browser-download links (e.g. the archive ZIP) that bypass `fetch`.
   */
  absoluteUrl(path: string): string {
    return `${this.baseUrl}${path}`;
  }

  /** The Filerobot key (`X-Filerobot-Key`), for query-param auth on direct downloads. */
  get authKey(): string | undefined {
    return (this.headers as Record<string, string>)['X-Filerobot-Key'];
  }

  private sendJson<T>(method: string, path: string, body: unknown): Promise<T> {
    return this.send<T>(new URL(`${this.baseUrl}${path}`), {
      method,
      headers: { 'Content-Type': 'application/json' },
      body: body === undefined ? undefined : JSON.stringify(body),
    });
  }

  private async send<T>(url: URL, init: RequestInit, retried = false): Promise<T> {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), TIMEOUT_MS);
    try {
      const response = await fetch(url.toString(), {
        ...init,
        headers: { ...this.headers, ...(init.headers as Record<string, string>) },
        signal: controller.signal,
      });
      clearTimeout(timeoutId);

      // A short-lived security-template key can expire mid-session — re-exchange
      // it once and retry, so the component recovers instead of 401-storming.
      if (response.status === 401 && !retried && this.auth?.mode === 'security-template') {
        const resolved = await resolveAuth(this.auth, this.apiDomain);
        this.headers = resolved.headers;
        return this.send<T>(url, init, true);
      }

      if (!response.ok) {
        let errorMsg = `API error: ${response.status} ${response.statusText}`;
        try {
          const body = await response.json();
          if (body?.msg) errorMsg = `API error: ${response.status} - ${body.msg}`;
        } catch {
          /* ignore parse errors */
        }
        throw new Error(errorMsg);
      }

      // 204 No Content (common for DELETE) has no body to parse.
      if (response.status === 204) return undefined as T;

      // Some gateways return an empty body on success (200/201) — tolerate it
      // instead of throwing a JSON parse error.
      const text = await response.text();
      if (!text) return undefined as T;
      const data = JSON.parse(text);
      if (data?.status === 'error') {
        throw new Error(`API error: ${data.msg || 'Unknown error'}`);
      }
      return data as T;
    } catch (err) {
      clearTimeout(timeoutId);
      if (err instanceof DOMException && err.name === 'AbortError') {
        throw new Error('API request timed out');
      }
      throw err;
    }
  }
}
