import { LitElement, html, css } from 'lit';
import { property } from 'lit/decorators.js';
import { customElement } from '../utils/define-element';
import './sfx-icon';

/** A single breadcrumb segment. Consumers may carry extra fields; only these are read. */
export interface BreadcrumbItem {
  /** Stable id emitted on navigate (folder uuid, label uuid, path key, …). */
  uuid: string;
  /** Display label. */
  name: string;
}

/**
 * Path breadcrumb: a clickable root + a trail of segments, the last shown as current.
 * Emits `breadcrumb-navigate` with `{ uuid }` (the root emits `uuid: ''`). Presentational
 * and store-agnostic — the host builds the `items` array and reacts to the event.
 */
@customElement('sfx-breadcrumb')
export class SfxBreadcrumb extends LitElement {
  static styles = css`
    :host {
      display: block;
      padding: 4px 20px 12px;
    }
    .breadcrumb {
      display: flex;
      align-items: center;
      gap: 4px;
      font-size: var(--sfx-font-size-sm, 0.875rem);
    }
    button {
      border: none;
      background: none;
      color: var(--sfx-muted-foreground, oklch(0.685 0.033 249.82));
      cursor: pointer;
      padding: 4px 6px;
      border-radius: 4px;
      font-family: var(--sfx-font-family, system-ui, sans-serif);
      font-size: var(--sfx-font-size-sm, 0.875rem);
    }
    button:first-child {
      margin-left: -6px;
    }
    button:hover {
      background: var(--sfx-muted, oklch(0.974 0.006 239.819));
      color: var(--sfx-foreground, oklch(0.37 0.022 248.413));
    }
    .current {
      color: var(--sfx-foreground, oklch(0.37 0.022 248.413));
      font-weight: 500;
      padding: 4px 6px;
    }
    sfx-icon {
      color: var(--sfx-muted-foreground, oklch(0.685 0.033 249.82));
    }
  `;

  @property({ type: Array }) items: BreadcrumbItem[] = [];
  @property() rootLabel = 'Root';

  private _navigate(uuid: string) {
    this.dispatchEvent(
      new CustomEvent('breadcrumb-navigate', { detail: { uuid }, bubbles: true, composed: true }),
    );
  }

  render() {
    if (this.items.length === 0) return html``;
    return html`
      <nav class="breadcrumb" aria-label="Breadcrumb">
        <button @click=${() => this._navigate('')}>${this.rootLabel}</button>
        ${this.items.map(
          (item, i) => html`
            <sfx-icon name="chevron-right" .size=${14}></sfx-icon>
            ${i < this.items.length - 1
              ? html`<button @click=${() => this._navigate(item.uuid)}>${item.name}</button>`
              : html`<span class="current">${item.name}</span>`}
          `,
        )}
      </nav>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'sfx-breadcrumb': SfxBreadcrumb;
  }
}
