import { LitElement, html, css } from 'lit';
import { property } from 'lit/decorators.js';
import { customElement } from '../utils/define-element';

@customElement('sfx-tooltip')
export class SfxTooltip extends LitElement {
  static styles = [
    css`
      :host {
        position: relative;
        display: inline-flex;
      }
      .tip {
        display: none;
        position: absolute;
        bottom: calc(100% + 6px);
        left: 50%;
        transform: translateX(-50%);
        white-space: nowrap;
        padding: 4px 8px;
        font-size: 0.75rem;
        background: var(--sfx-foreground, oklch(0.37 0.022 248.413));
        color: var(--sfx-background, oklch(1 0 0));
        border-radius: 4px;
        pointer-events: none;
        z-index: 100;
      }
      .tip.bottom {
        bottom: auto;
        top: calc(100% + 6px);
      }
      :host(:hover) .tip {
        display: block;
      }
    `,
  ];

  @property() text = '';
  /** Which side of the trigger the tip opens on (default `top`; use `bottom` near the
   *  viewport's top edge, e.g. toolbar buttons). */
  @property() placement: 'top' | 'bottom' = 'top';

  render() {
    return html`
      <slot></slot>
      <div class="tip ${this.placement === 'bottom' ? 'bottom' : ''}">${this.text}</div>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'sfx-tooltip': SfxTooltip;
  }
}
